// ═══ CAUSE 1: Unbounded recursion — missing base case ═══
public int factorial(int n) {
    return n * factorial(n - 1);  // NO base case! Never stops!
    // factorial(5) → factorial(4) → factorial(3) → ... → factorial(-999999) → SOE!
}
// FIX:
public int factorial(int n) {
    if (n <= 1) return 1;  // BASE CASE!
    return n * factorial(n - 1);
}

// ═══ CAUSE 2: Mutual recursion — A calls B, B calls A ═══
public boolean isEven(int n) { return n == 0 || isOdd(n - 1); }
public boolean isOdd(int n) { return n != 0 && isEven(n - 1); }
// isEven(100000) → isOdd(99999) → isEven(99998) → ... → SOE!
// FIX: convert to iteration:
public boolean isEven(int n) { return n % 2 == 0; }

// ═══ CAUSE 3: Cyclic toString() — VERY COMMON in JPA/banking! ═══
public class Account {
    private List<Trade> trades;
    @Override
    public String toString() {
        return "Account{trades=" + trades + "}";  // calls Trade.toString()
    }
}
public class Trade {
    private Account account;
    @Override
    public String toString() {
        return "Trade{account=" + account + "}";  // calls Account.toString()!
    }
}
// account.toString() → trade.toString() → account.toString() → INFINITE → SOE!
// FIX: exclude parent reference in toString():
// return "Trade{id=" + id + "}";  // DON'T include account!

// ═══ SOE vs OOM comparison ═══
// StackOverflowError:                 OutOfMemoryError:
// Per-thread stack (~512KB)            Shared heap (~256MB-4GB)
// Too many frames (depth)              Too many objects (space)
// Code bug: recursion                  Memory leak / large data
// Fix: base case, iteration, -Xss     Fix: fix leak, -Xmx, profiler
// Thread-local (one thread dies)       JVM-wide (everything affected)
// Recoverable: catch + continue        Usually fatal: heap corrupted

// ═══ OOM types ═══
// java.lang.OutOfMemoryError: Java heap space     ← heap full
// java.lang.OutOfMemoryError: Metaspace            ← too many classes loaded
// java.lang.OutOfMemoryError: GC overhead limit     ← GC runs >98% time, recovers <2% heap
// java.lang.OutOfMemoryError: unable to create new native thread ← OS thread limit
