// ─── File: src/test/java/com/bank/soe/StackOverflowTest.java ───
package com.bank.soe;

import org.junit.jupiter.api.Test;
import java.util.List;
import java.util.ArrayList;
import static org.assertj.core.api.Assertions.*;

class StackOverflowTest {

    // ═══ UNBOUNDED RECURSION ═══
    int badFactorial(int n) {
        return n * badFactorial(n - 1);  // no base case!
    }

    int goodFactorial(int n) {
        if (n <= 1) return 1;  // base case!
        return n * goodFactorial(n - 1);
    }

    @Test
    void unboundedRecursion_throwsSOE() {
        assertThatThrownBy(() -> badFactorial(5))
            .isInstanceOf(StackOverflowError.class);
    }

    @Test
    void fixedRecursion_works() {
        assertThat(goodFactorial(5)).isEqualTo(120);
        assertThat(goodFactorial(10)).isEqualTo(3628800);
    }

    // ═══ CYCLIC toString — JPA-style ═══
    static class Account {
        String id;
        List<Trade> trades = new ArrayList<>();
        @Override public String toString() {
            return "Account{id=" + id + ", trades=" + trades + "}";
        }
    }

    static class Trade {
        String id;
        Account account;  // back-reference!
        @Override public String toString() {
            return "Trade{id=" + id + ", account=" + account + "}";  // CYCLIC!
        }
    }

    @Test
    void cyclicToString_throwsSOE() {
        Account acc = new Account();
        acc.id = "SAV2001";
        Trade trade = new Trade();
        trade.id = "TRD-001";
        trade.account = acc;
        acc.trades.add(trade);

        assertThatThrownBy(acc::toString)
            .isInstanceOf(StackOverflowError.class);
        // Account.toString() → Trade.toString() → Account.toString() → ∞ → SOE!
    }

    // ═══ FIX: exclude parent reference ═══
    static class SafeTrade {
        String id;
        Account account;
        @Override public String toString() {
            return "Trade{id=" + id + "}";  // DON'T include account!
        }
    }

    @Test
    void fixedToString_works() {
        SafeTrade trade = new SafeTrade();
        trade.id = "TRD-001";
        assertThat(trade.toString()).isEqualTo("Trade{id=TRD-001}");
    }

    // ═══ CONVERT RECURSION TO ITERATION ═══
    long iterativeFactorial(int n) {
        long result = 1;
        for (int i = 2; i <= n; i++) result *= i;
        return result;
    }

    @Test
    void iterative_noSOE() {
        assertThat(iterativeFactorial(20)).isEqualTo(2432902008176640000L);
        // No recursion → no stack growth → works for ANY input size!
    }
}
